/* Minimal declarations of the CasADi-generated C ABI used by FastSQP.
 *
 * The problem-specific C file generated by the fastsqp adapter exports three
 * functions with fixed names and dense outputs (column-major):
 *
 *   dyn(x,u)   -> [ xnext(nx), A=dxnext/dx (nx*nx), B=dxnext/du (nx*nu) ]
 *   costs(x,u,xref,uref) -> [ gx(nx), gu(nu), Hxx(nx*nx), Huu(nu*nu), Hxu(nx*nu) ]
 *   costN(x,xref)        -> [ gx(nx), Hxx(nx*nx) ]
 *
 * CasADi's calling convention is
 *   int f(const casadi_real** arg, casadi_real** res,
 *         casadi_int* iw, casadi_real* w, int mem);
 * with companion f_work(sz_arg, sz_res, sz_iw, sz_w).
 */
#ifndef FASTSQP_CASADI_ABI_H
#define FASTSQP_CASADI_ABI_H

typedef long long int casadi_int;
typedef double casadi_real;

extern "C" {
int dyn(const casadi_real** arg, casadi_real** res,
        casadi_int* iw, casadi_real* w, int mem);
int dyn_work(casadi_int* sz_arg, casadi_int* sz_res,
             casadi_int* sz_iw, casadi_int* sz_w);

int costs(const casadi_real** arg, casadi_real** res,
          casadi_int* iw, casadi_real* w, int mem);
int costs_work(casadi_int* sz_arg, casadi_int* sz_res,
               casadi_int* sz_iw, casadi_int* sz_w);

int costN(const casadi_real** arg, casadi_real** res,
          casadi_int* iw, casadi_real* w, int mem);
int costN_work(casadi_int* sz_arg, casadi_int* sz_res,
               casadi_int* sz_iw, casadi_int* sz_w);
}
#endif
